using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace Iris {
    public sealed partial class NotchWindow {
        CancellationTokenSource integrationLogin;int integrationDialogVersion;
        void CancelIntegrationLogin(){integrationDialogVersion++;if(integrationLogin!=null){integrationLogin.Cancel();integrationLogin.Dispose();integrationLogin=null;}}
        void ShowIntegrationResult(string title,string message){if(addonWindow!=null)return;OpenAddonWindow(title);var panel=AddonPanel();panel.Children.Add(AddonNote(message));panel.Children.Add(Btn(L.T("Schließen"),CloseAddonWindow));ShowAddonDialogPage("integration-result",AddonScroll(panel),1);}
        void ShowIntegrationConnections(){
            CancelIntegrationLogin();if(addonWindow==null)OpenAddonWindow(L.T("Verbindungen"));var owner=addonWindow;int generation=integrationDialogVersion;var panel=AddonPanel();panel.Children.Add(AddonChoice("‹ Add-ons",L.T("Zurück zur Bibliothek"),delegate{CancelIntegrationLogin();RenderAddonLibrary021();}));
            string directory=Path.Combine(root,dataFolder);AddonConnections current;try{current=AddonConnectionStore.Read(directory);}catch(Exception ex){panel.Children.Add(AddonNote(ex.Message));ShowAddonDialogPage("connections-error",panel,1);return;}
            panel.Children.Add(Text("OBS Studio",17,ink));panel.Children.Add(AddonNote(L.T("OBS → Werkzeuge → WebSocket-Servereinstellungen. Nur lokaler Zugang; Passwort bleibt Windows-verschlüsselt auf diesem PC.")));var endpoint=AddonField(panel,L.T("Serveradresse"),current.ObsEndpoint,false);panel.Children.Add(Text(L.T("Passwort · leer lassen, um vorhandenes zu behalten"),11,muted));var password=new PasswordBox{Height=32,MaxLength=512,Margin=new Thickness(0,4,0,10),Background=new SolidColorBrush(Color.FromRgb(39,39,41)),Foreground=Brushes.White};panel.Children.Add(password);
            panel.Children.Add(Text("Spotify Connect",17,ink));panel.Children.Add(AddonNote(L.T("Für Spezialaktionen: eigene Spotify-App im Developer Dashboard anlegen und diese Redirect-Adresse registrieren:\n")+SpotifyApi.Redirect+L.T("\nClient-ID eintragen, speichern und verbinden. Kein Client-Secret. Spotify verlangt im Development Mode Premium und ein freigegebenes Konto.")));var client=AddonField(panel,"Spotify-Client-ID",current.SpotifyClientId,false);client.MaxLength=32;var state=Text(current.SpotifyRefresh.Length>0?L.T("Anmeldung gespeichert · Verbindung noch nicht live geprüft"):L.T("Noch nicht verbunden"),11,muted);state.TextWrapping=TextWrapping.Wrap;state.Margin=new Thickness(0,0,0,9);panel.Children.Add(state);
            Func<bool> save=delegate{try{AddonConnectionStore.Update(directory,c=>{c.ObsEndpoint=endpoint.Text.Trim();if(password.Password.Length>0)c.ObsPassword=password.Password;if(c.SpotifyClientId!=client.Text.Trim()){c.SpotifyAccess=c.SpotifyRefresh="";c.SpotifyExpires=DateTime.MinValue;}c.SpotifyClientId=client.Text.Trim();});password.Clear();state.Text=L.T("Verbindungen gespeichert. Speichern führt keine Aktion aus.");return true;}catch(Exception ex){state.Text=ex.Message;return false;}};
            panel.Children.Add(Btn(L.T("Speichern"),delegate{save();}));var connect=Btn(L.T("Spotify verbinden …"),delegate{if(uiTesting){state.Text=L.T("QA: Anmeldung nicht geöffnet; Mikrofon und Zwischenablage bleiben unberührt.");return;}if(integrationLogin!=null){state.Text=L.T("Die Anmeldung läuft bereits. Im Browser fortfahren oder abbrechen.");return;}if(!save())return;var cancellation=integrationLogin=new CancellationTokenSource();var token=cancellation.Token;state.Text=L.T("Im Browser anmelden · Abbrechen jederzeit möglich");Task.Factory.StartNew(delegate{try{new SpotifyApi(directory).Connect(uri=>nativeAddonHost.Launch(uri,"",""),token);return L.T("Spotify-Anmeldung gespeichert.");}catch(OperationCanceledException){return L.T("Anmeldung abgebrochen.");}catch(Exception ex){return ex.GetBaseException().Message;}}).ContinueWith(task=>Dispatcher.BeginInvoke(new Action(delegate{if(owner!=addonWindow||generation!=integrationDialogVersion||shuttingDown)return;if(integrationLogin==cancellation){integrationLogin=null;cancellation.Dispose();}state.Text=task.Result;})));});connect.Margin=new Thickness(0,7,0,0);panel.Children.Add(connect);
            panel.Children.Add(AddonChoice(L.T("Anmeldung abbrechen"),L.T("Lokalen Anmeldezugang sofort schließen"),delegate{CancelIntegrationLogin();state.Text=L.T("Anmeldung abgebrochen. Seite neu öffnen, um erneut zu verbinden.");}));
            panel.Children.Add(AddonChoice(L.T("Spotify trennen"),L.T("Nur gespeicherte Iris-Anmeldung löschen; widerrufen zusätzlich im Spotify-Konto möglich"),delegate{CancelIntegrationLogin();try{AddonConnectionStore.Update(directory,c=>{c.SpotifyAccess=c.SpotifyRefresh="";c.SpotifyExpires=DateTime.MinValue;});state.Text=L.T("Spotify getrennt.");}catch(Exception ex){state.Text=ex.Message;}}));
            panel.Children.Add(AddonChoice(L.T("OBS-Passwort entfernen"),L.T("Passwort nur aus Iris entfernen"),delegate{try{AddonConnectionStore.Update(directory,c=>c.ObsPassword="");password.Clear();state.Text=L.T("OBS-Passwort aus Iris entfernt.");}catch(Exception ex){state.Text=ex.Message;}}));ShowAddonDialogPage("connections",AddonScroll(panel),1);
        }
        AddonResult RunLocalIntegration(AddonAction action){return (AddonResult)Dispatcher.Invoke(new Func<AddonResult>(delegate{
            if(shuttingDown)throw new OperationCanceledException();string kind=action.Kind;
            if(kind.EndsWith("-volume-up")||kind.EndsWith("-volume-down")||kind=="spotify-mute"||kind=="applemusic-mute"){
                string process=kind.StartsWith("spotify-")?"Spotify":"AppleMusic";var sources=audioSnapshot.Where(s=>string.Equals(s.ProcessName,process,StringComparison.OrdinalIgnoreCase)||s.Package!=null&&s.Package.StartsWith(process=="Spotify"?"SpotifyAB.SpotifyMusic_":"AppleInc.AppleMusicWin_",StringComparison.OrdinalIgnoreCase)).ToArray();if(sources.Length!=1)return AddonResult.Of(AddonResultCode.Unavailable,L.T("Keine eindeutige Audioquelle für ")+process+L.T(". Windows-Lautstärke bleibt unverändert."));var source=sources[0];if(kind.EndsWith("-mute"))ChangeSourceMute(source.Key,null);else SetSourceVolume(source.Key,Math.Max(0,Math.Min(1,SourceLevel(source.Key)+(kind.EndsWith("-up")?.05:-.05))));return AddonResult.Of(AddonResultCode.Succeeded,L.T("Lautstärkebefehl an ")+source.Name+L.T(" übergeben."));
            }
            if(kind=="hardware-mixer"){SwitchPage("Mixer",true);Open();return AddonResult.Of(AddonResultCode.Succeeded,L.T("Iris-Mixer geöffnet."));}
            if(kind=="hardware-gaming"){ShowSettings();settingsSection="Gaming";RenderSettingsSection();return AddonResult.Of(AddonResultCode.Succeeded,L.T("Gaming-Einstellungen geöffnet."));}
            if(kind=="spotify-player"||kind=="applemusic-player"){if(!prefs.Music)return AddonResult.Of(AddonResultCode.Unavailable,L.T("Musik zuerst unter Einstellungen aktivieren."));SwitchPage("Musik",true);Open();return AddonResult.Of(AddonResultCode.Succeeded,L.T("Vorhandenen Player geöffnet; er zeigt die aktuelle Windows-Medienquelle."));}
            if(kind.StartsWith("productivity-timer")){if(kind=="productivity-timer-start"){int minutes=int.Parse(action.Target);prefs.Minutes=minutes;prefs.Seconds=0;minutesBox.Text=minutes.ToString("00");secondsBox.Text="00";countdown.Reset(minutes*60);timerFinished=false;finishedTimer.Stop();countdown.Start(DateTime.UtcNow);ShowEyes(false);Save();RefreshTimer();}else if(kind=="productivity-timer-toggle")ToggleTimer();else if(kind=="productivity-timer-reset"){countdown.Reset(ConfiguredSeconds());timerFinished=false;finishedTimer.Stop();Save();RefreshTimer();}SwitchPage("Timer",true);Open();return AddonResult.Of(AddonResultCode.Succeeded,L.T("Iris-Timer ")+(countdown.Running?L.T("läuft"):L.T("geöffnet")));}
            return AddonResult.Of(AddonResultCode.Unavailable,L.T("Diese lokale Funktion ist nicht verfügbar."));
        }));}
    }
